-- ===========================================================================
-- Puntos de control - GLOBALG.A.P. IFA v6 (resumen divulgativo)
-- ===========================================================================

INSERT INTO control_points (chapter_id, ref, title, description, level, guidance, evidence_examples, applicable_scopes, sort_order)
SELECT ch.id, cp.ref, cp.title, cp.description, cp.level, cp.guidance, cp.evidence_examples, cp.scopes, cp.sort_order
FROM audit_standards s
JOIN standard_chapters ch ON ch.standard_id = s.id
JOIN (VALUES
 -- LEGAL
 ('LEGAL','AF 1.1','Titularidad legal y ubicación del sitio de producción','El productor dispone de documentación que acredita la titularidad o el derecho de uso del terreno y de mapas/planos que identifican los sitios de producción.','MAJOR_MUST','Escrituras, contratos de arrendamiento, coordenadas GPS y croquis de las parcelas.','Contrato de arrendamiento; mapa con parcelas y coordenadas','ALL',1),
 ('LEGAL','AF 1.2','Evaluación de riesgos del sitio','Existe una evaluación de riesgos documentada del nuevo y del actual sitio de producción que cubre riesgos físicos, químicos y biológicos.','MAJOR_MUST','Debe considerar el historial de uso del suelo, actividades colindantes y contaminación potencial del agua y del suelo.','Documento de evaluación de riesgos del sitio con fecha y firma','ALL',2),
 ('LEGAL','AF 1.3','Plan de gestión con medidas correctoras','La evaluación de riesgos conduce a un plan de gestión con medidas para mitigar los riesgos identificados.','MINOR_MUST','El plan indica responsables y plazos.','Plan de acción derivado de la evaluación de riesgos','ALL',3),
 -- MGMT
 ('MGMT','AF 2.1','Trazabilidad del producto certificado','El sistema permite trazar el producto certificado desde la parcela hasta el cliente y a la inversa (un paso atrás, un paso adelante).','MAJOR_MUST','Identificación de lotes y registros de entrada/salida. Alineado con el art. 18 del Reg. (CE) 178/2002 e ISO 22005.','Registros de lote; albaranes; prueba de trazabilidad','ALL',1),
 ('MGMT','AF 2.2','Ejercicio de trazabilidad y balance de masas','Se realiza al menos una vez al año una prueba de trazabilidad y de balance de masas del producto certificado.','MAJOR_MUST','El balance compara cantidad cosechada, almacenada y vendida como certificada.','Informe del ejercicio de trazabilidad; cálculo de balance de masas','ALL',2),
 ('MGMT','AF 2.3','Procedimiento de retirada y recuperación de producto','Existe un procedimiento documentado de retirada/recuperación de producto y se prueba anualmente.','MAJOR_MUST','El procedimiento incluye lista de contactos actualizada y responsabilidades.','Procedimiento de retirada; registro del simulacro anual','ALL',3),
 ('MGMT','AF 2.4','Gestión de reclamaciones','Se registran las reclamaciones relacionadas con el cumplimiento del estándar y las acciones tomadas.','MINOR_MUST','Registro con fecha, descripción, análisis de causa y acción.','Registro de reclamaciones','ALL',4),
 ('MGMT','AF 2.5','Autoevaluación anual','El productor realiza una autoevaluación anual frente a la lista de verificación aplicable antes de la auditoría externa.','MAJOR_MUST','Requisito del Reglamento General de GLOBALG.A.P. Debe cubrir todos los puntos aplicables y las no conformidades detectadas deben cerrarse.','Checklist de autoevaluación firmado y fechado','ALL',5),
 ('MGMT','AF 2.6','Conservación de registros (mínimo por periodo requerido)','Los registros que demuestran el cumplimiento se conservan y están disponibles durante al menos el periodo exigido por el estándar.','MINOR_MUST','GLOBALG.A.P. exige disponibilidad de registros de al menos los 90 días previos a la inspección; normalmente se conservan 2 años.','Archivo de registros de campaña','ALL',6),
 -- PROD
 ('PROD','CB 3.1','Material de reproducción vegetal','El material vegetal procede de proveedores que garantizan la sanidad vegetal y, cuando aplica, la ausencia de OMG no autorizados.','MINOR_MUST','Conservar facturas y pasaportes fitosanitarios / certificados de calidad de la semilla o plántula.','Facturas y certificados del material vegetal','CROPS',1),
 ('PROD','CB 3.2','Gestión del suelo y de sustratos','Existen mapas de suelos y prácticas que preservan su estructura y reducen la erosión y la compactación.','MINOR_MUST','Análisis de suelo periódico; rotación; cubiertas vegetales.','Análisis de suelo; plan de laboreo','CROPS',2),
 ('PROD','CB 4.1','Plan y registros de fertilización','La fertilización se basa en las necesidades del cultivo y análisis; se registran fecha, producto, dosis, parcela y aplicador.','MAJOR_MUST','Debe respetar los límites de nitrógeno en zonas vulnerables a nitratos (Directiva 91/676/CEE).','Registros de aplicación de fertilizantes; análisis foliar/de suelo','CROPS',3),
 ('PROD','CB 4.2','Almacenamiento de fertilizantes','Los fertilizantes se almacenan separados de los productos fitosanitarios y del producto cosechado, en zona limpia y seca.','MINOR_MUST','Evitar contaminación cruzada y riesgos de seguridad.','Fotos del almacén; inventario','CROPS',4),
 ('PROD','CB 5.1','Gestión del agua de riego y evaluación de riesgos','Se gestiona el uso del agua de riego y existe una evaluación de riesgos de la calidad del agua según su origen y uso.','MAJOR_MUST','Considerar aptitud microbiológica y química del agua; frecuencia de análisis según riesgo. Directiva Marco del Agua 2000/60/CE.','Evaluación de riesgos del agua; resultados analíticos','ALL',5),
 ('PROD','CB 5.2','Registro del consumo de agua y eficiencia','Se registra el consumo de agua y se aplican medidas de eficiencia en el riego.','RECOMMENDATION','Contadores, riego localizado, programación según necesidades del cultivo.','Lecturas de contador; plan de riego','ALL',6),
 ('PROD','CB 7.1','Gestión integrada de plagas (GIP)','Se aplican y documentan medidas de prevención, observación/monitoreo e intervención conforme a la gestión integrada de plagas.','MAJOR_MUST','Requisito de la Directiva 2009/128/CE. Registrar umbrales, trampas y decisiones de tratamiento.','Registros de monitoreo; justificación de tratamientos','CROPS',7),
 ('PROD','CB 7.2','Uso de productos fitosanitarios autorizados','Solo se utilizan productos fitosanitarios autorizados en el país de producción para el cultivo objetivo.','MAJOR_MUST','Comprobación frente al registro oficial de productos fitosanitarios (Reg. (CE) 1107/2009).','Lista de productos autorizados usados; etiquetas','CROPS',8),
 ('PROD','CB 7.3','Registros de aplicación de fitosanitarios','Cada aplicación se registra: cultivo, parcela, fecha, producto y nº de registro, plaga objetivo, dosis, equipo, aplicador y plazo de seguridad.','MAJOR_MUST','Los registros deben permitir verificar el respeto del plazo de seguridad antes de la cosecha.','Cuaderno de campo / registros de aplicación','CROPS',9),
 ('PROD','CB 7.4','Cálculo del plazo de seguridad y respeto de LMR','Se respeta el plazo de seguridad de cada producto y se gestiona el riesgo de superar los LMR (Reg. (CE) 396/2005).','MAJOR_MUST','Considerar LMR del mercado de destino cuando son más estrictos.','Registros de aplicación con fecha; analítica de residuos','CROPS',10),
 ('PROD','CB 7.5','Equipos de aplicación calibrados e inspeccionados','Los equipos de aplicación de fitosanitarios se mantienen, calibran y superan la inspección técnica obligatoria.','MINOR_MUST','Directiva 2009/128/CE exige inspección periódica del equipo.','Certificado de inspección del equipo; registro de calibración','CROPS',11),
 ('PROD','CB 7.6','Gestión de sobrantes y caldos de tratamiento','Los sobrantes de caldo y el agua de lavado del equipo se gestionan evitando la contaminación de aguas.','MINOR_MUST','Aplicar sobre el cultivo tratado o en zona de biodepuración.','Procedimiento de gestión de sobrantes','CROPS',12),
 -- HARV
 ('HARV','FV 8.1','Higiene en la cosecha','Existe una evaluación de riesgos de higiene en la cosecha y los trabajadores han recibido formación e instrucciones de higiene.','MAJOR_MUST','Cubrir estado de salud, lavado de manos, uso de utensilios limpios y prohibición de comer en las parcelas.','Evaluación de riesgos de higiene; registros de formación','FRUIT_VEG',1),
 ('HARV','FV 8.2','Envases y contenedores de cosecha','Los envases reutilizables se limpian y se usan solo para producto alimentario.','MINOR_MUST','Protocolo de limpieza y almacenamiento de cajas y palots.','Procedimiento e historial de limpieza de envases','FRUIT_VEG',2),
 ('HARV','FV 8.3','Transporte del producto cosechado','El producto se transporta en condiciones que evitan contaminación y deterioro (limpieza del vehículo, separación de sustancias de riesgo).','MINOR_MUST','Registro de limpieza del vehículo o del remolque.','Checklist de limpieza del transporte','FRUIT_VEG',3),
 -- FOOD
 ('FOOD','FV 9.1','Análisis de peligros y puntos de control (APPCC)','Se ha realizado un análisis de peligros de las actividades de producción y manipulación con identificación de medidas de control.','MAJOR_MUST','Basado en los principios del Codex / Reg. (CE) 852/2004. Revisado al menos anualmente.','Estudio APPCC; diagrama de flujo; plan de control','ALL',1),
 ('FOOD','FV 9.2','Higiene del personal en manipulación','Normas de higiene personal implantadas y verificadas en las áreas de manipulación (ropa, joyas, heridas, enfermedades).','MAJOR_MUST','Cartelería, formación y supervisión.','Instrucción de higiene; registros de formación; inspecciones','ALL',2),
 ('FOOD','FV 9.3','Agua de lavado en contacto con el producto','El agua que entra en contacto con el producto tras la cosecha es apta (potable o de aptitud demostrada) y se controla su calidad.','MAJOR_MUST','Análisis microbiológico con frecuencia basada en riesgo; control de cloro u otro tratamiento.','Resultados analíticos del agua; registros de dosificación','ALL',3),
 ('FOOD','FV 9.4','Instalaciones y equipos de manipulación','Las instalaciones de manipulación, almacén y frío se mantienen limpias, ordenadas y en buen estado, con control de plagas.','MINOR_MUST','Plan de limpieza y desinfección; plan de control de plagas con mapa de cebos.','Registros de limpieza; informes de control de plagas','ALL',4),
 ('FOOD','FV 9.5','Análisis de residuos de plaguicidas','Existe un plan anual de muestreo y análisis de residuos y un procedimiento de actuación ante superación de LMR.','MAJOR_MUST','El laboratorio debe estar acreditado ISO/IEC 17025 para los analitos.','Plan de muestreo; boletines de análisis; procedimiento de exceso de LMR','ALL',5),
 ('FOOD','FV 9.6','Gestión de alérgenos y cuerpos extraños','Se identifican y controlan los riesgos de contaminación por cuerpos extraños, vidrio, plástico quebradizo y alérgenos.','MINOR_MUST','Registro de roturas de vidrio/plástico; inspección de mallas y luminarias.','Procedimiento de cuerpos extraños; registro de incidencias','ALL',6),
 -- ENV
 ('ENV','AF 10.1','Plan de gestión de residuos y contaminantes','Se identifican los residuos y contaminantes generados y existe un plan documentado para su reducción, reutilización y eliminación.','MINOR_MUST','Incluir plásticos agrícolas, envases de fitosanitarios (SIGFITO/sistema equivalente) y aceites usados.','Plan de gestión de residuos; justificantes de gestor autorizado','ALL',1),
 ('ENV','AF 10.2','Eficiencia energética','Se registra el consumo de energía y se aplican medidas para mejorar la eficiencia.','RECOMMENDATION','Seguimiento de combustible y electricidad; plan de mejora.','Registros de consumo energético','ALL',2),
 ('ENV','AF 10.3','Conservación de la biodiversidad','Existe un plan de conservación de la biodiversidad que convierte zonas improductivas en áreas de conservación cuando es viable.','MINOR_MUST','Setos, márgenes, refugios de fauna, listado de especies.','Plan de biodiversidad; mapa de áreas de conservación','ALL',3),
 -- WORK
 ('WORK','AF 11.1','Evaluación de riesgos laborales','Existe una evaluación de riesgos para la seguridad y salud de los trabajadores, documentada y actualizada.','MAJOR_MUST','Cubrir todas las actividades y equipos; revisar tras cambios o accidentes.','Documento de evaluación de riesgos laborales','ALL',1),
 ('WORK','AF 11.2','Procedimientos de seguridad y salud','Hay procedimientos e instrucciones claras de seguridad para las actividades peligrosas, accesibles a los trabajadores.','MINOR_MUST','Instrucciones en un idioma comprensible; señalización.','Procedimientos de trabajo seguro; fichas de instrucción','ALL',2),
 ('WORK','AF 11.3','Formación de los trabajadores','Los trabajadores reciben formación adecuada a sus tareas, incluida la manipulación segura de productos químicos.','MAJOR_MUST','Registros con fecha, contenido, formador y firma del asistente.','Registros de formación; certificados de aplicador de fitosanitarios','ALL',3),
 ('WORK','AF 11.4','Equipos de protección individual (EPI)','Se proporcionan, mantienen y almacenan correctamente los EPI necesarios según la etiqueta de los productos y la evaluación de riesgos.','MAJOR_MUST','EPI limpios, en buen estado y guardados fuera de la zona de químicos.','Inventario de EPI; registros de entrega; inspección visual','ALL',4),
 ('WORK','AF 11.5','Instalaciones de bienestar','Los trabajadores disponen de agua potable, aseos, lugar para comer y zona de descanso limpios y accesibles.','MINOR_MUST','Adecuados al número de trabajadores y a la ubicación de las parcelas.','Inspección de instalaciones; fotos','ALL',5),
 ('WORK','AF 11.6','Primeros auxilios y emergencias','Hay botiquines accesibles, personal formado en primeros auxilios y procedimientos de emergencia con puntos de encuentro señalizados.','MAJOR_MUST','Números de emergencia visibles; simulacros cuando aplica.','Contenido y ubicación de botiquines; certificados de primeros auxilios','ALL',6),
 ('WORK','AF 11.7','Almacén de productos fitosanitarios','El almacén de fitosanitarios es seguro, ventilado, con acceso restringido, contención de derrames y separación de otros materiales.','MAJOR_MUST','Estanterías no absorbentes, señalización, kit de derrames e inventario actualizado.','Inspección del almacén; inventario; ficha de datos de seguridad','CROPS',7)
) AS cp(chapter_code, ref, title, description, level, guidance, evidence_examples, scopes, sort_order)
  ON cp.chapter_code = ch.code
WHERE s.code = 'GLOBALGAP_IFA_V6';
